function jobsList(){const q=(route.data.query||'').toLowerCase(),filter=route.data.filter||'all';const list=jobs.filter(j=>(filter==='all'||j.path===(filter==='match'?state.path:filter))&&(j.title+' '+company(j.company).name+' '+j.city).toLowerCase().includes(q));return `<p class="small">${list.length} lowongan demo ditemukan</p>${list.length?list.map(jobCard).join(''):empty('Belum ditemukan','Ubah kata kunci atau filter pencarian.')}`}
