function navGroup(){if(['modules','module','lesson','quiz','quizResult','caseList','case','caseResult'].includes(route.name))return'modules';if(['path','paths','recommendation'].includes(route.name))return'paths';if(route.name==='progress')return'progress';if(['profile','editProfile','portfolio','certificates','certificate','settings','help','cv','found','saved','applications','application','notifications'].includes(route.name))return'profile';return'home'}
function render(){
 const page=views[route.name](),nav=!['welcome','login','cvProcessing'].includes(route.name)&&(!onboarding.includes(route.name)||state.onboarded),unread=state.notificationEnabled&&state.notifications.filter(n=>!n.read).length;
 const header=page.noHeader?'':`<div class="app-header"><div class="left">${page.back===false?'':btn(icon('back'),'back',{},'icon-button')}<h1>${page.title||''}</h1></div><div class="row" style="gap:0">${page.extra||(!onboarding.includes(route.name)&&route.name!=='notifications'?btn(icon('bell')+(unread?`<span class="badge-dot">${unread}</span>`:''),'go',{name:'notifications'},'icon-button'):'')}</div></div>`;
 $('#app').innerHTML=header+`<div class="app-scroll" id="screen-content">${page.body}</div>`+(nav?`<nav class="app-nav" aria-label="Navigasi utama aplikasi">${[['home','Beranda','home'],['paths','Jalur','compass'],['modules','Task','task'],['progress','Progres','chart'],['profile','Profil','user']].map(([r,t,i])=>routeButton(icon(i)+`<span>${t}</span>`,r,{},navGroup()===r?'active':'')).join('')}</nav>`:'');
 const group=onboarding.includes(route.name)?0:['path','companies','company'].includes(route.name)?1:['modules','module','lesson','quiz','quizResult'].includes(route.name)?2:['caseList','case','caseResult','portfolio'].includes(route.name)?3:['jobs','job','apply','saved'].includes(route.name)?4:5;
 const contexts=[['Mulai dari dirimu.','CV contoh atau kuesioner menjadi titik awal. Profil dapat dikoreksi sebelum memilih jalur.'],['Pilih arah, bukan batas.','Jalur membantu menyusun latihan; pengguna tetap dapat menjelajahi materi dan peluang lain.'],['Belajar dengan tujuan.','Materi singkat diikuti kuis dan umpan balik. XP berasal dari aktivitas yang diselesaikan.'],['Latih keputusan, simpan buktinya.','Kasus kerja bertahap menunjukkan alasan di balik pilihan, lalu mengisi portofolio latihan.'],['Temukan peluang yang relevan.','Jelajahi perusahaan dan lowongan demo, simpan pilihan, lalu latih pembuatan lamaran.'],['Ketahui langkah berikutnya.','Lamaran, pesan, profil, dan notifikasi dapat dibuka bebas. Pembaruan status ditandai sebagai simulasi.']];
 $('#screen-count').textContent=String(group+1);$('#context-title').textContent=contexts[group][0];$('#context-copy').textContent=contexts[group][1];$$('.flow-menu button').forEach((b,i)=>b.classList.toggle('current',i===group));
}
function profileAward(){if(profileCompletion(state)===100)award(state,'profile',50)}
function chatReply(text){const q=text.toLowerCase();return /lamar|status|rekrut/.test(q)?'Buka Profil → Lamaran saya → pilih posisi. Status berubah hanya lewat tombol “Simulasikan tahap berikutnya”; tidak ada respons perusahaan nyata.':/portofolio|sertifikat|bukti/.test(q)?'Portofolio menyimpan hasil kasus dan modul lulus. Sertifikat demo memerlukan 8 modul dan kasus jalur yang sama dengan nilai minimal 60.':/cv|profil/.test(q)?'Buka Profil → CV dan profil pengalaman. Kamu bisa memakai CV contoh atau memilih berkas lokal lalu mengisi profil manual. Tidak ada analisis AI di prototipe ini.':/belajar|modul|task|kuis/.test(q)?'Buka tab Task, pilih materi mana pun, baca 3 bagian, lalu kerjakan kuis. Nilai minimal 60 menandai modul selesai dan memberi 150 XP sekali.':'Aku hanya pendamping demo berbasis aturan. Coba tanyakan tentang modul, CV, portofolio, atau status lamaran. Untuk pertanyaan profesional nyata, verifikasi dengan mentor atau pihak terkait.'}
