 selectPath:d=>{state.path=d.id;save();render()},confirmPath:()=>choosePath(state.path),activatePath:d=>{state.path=d.id;state.onboarded=true;save();go('modules')},
 scoreInfo:()=>toast('Skor aturan: dasar 40 + proporsi skill cocok × 30 + tiap minat cocok × 20, maksimal 96. Bukan penilaian rekrutmen.'),
 togglePathSave:d=>{state.savedPaths=state.savedPaths||[];state.savedPaths=state.savedPaths.includes(d.id)?state.savedPaths.filter(x=>x!==d.id):[...state.savedPaths,d.id];save();toast(state.savedPaths.includes(d.id)?'Jalur disimpan.':'Jalur dihapus dari tersimpan.')},
 quizPick:d=>{route.data.choice=d.index;render()},
 quizNext(){const d=route.data;if(d.choice===undefined)return toast('Pilih satu jawaban lebih dulu.');const answers=[...d.answers,d.choice];if(d.step<4)return go('quiz',{...d,step:d.step+1,answers,choice:undefined});const questions=quizFor(d.path,d.index),score=answers.filter((a,i)=>a===questions[i].correct).length*20,first=completeModule(state,d.path,d.index,score);lastQuiz={path:d.path,index:d.index,questions,answers,score,first};if(first)addNotice(state,'Modul selesai','Kuis lulus dengan nilai '+score+'. +150 XP pertama kali.','task','progress');save();go('quizResult')},
 casePick:d=>{route.data.choice=d.index;render()},
 caseNext(){const d=route.data;if(d.choice===undefined)return toast('Pilih tindakanmu lebih dulu.');const c=cases[d.path],answers=[...d.answers,d.choice];if(d.step<2)return go('case',{...d,step:d.step+1,answers,choice:undefined});const result=completeCase(state,d.path,answers.map((a,i)=>c.steps[i].options[a][1]));lastCase={...result,path:d.path,choices:answers,steps:c.steps};if(result.first)addNotice(state,'Bukti kasus tersimpan','Latihan kasus lulus. +200 XP pertama kali.','task','portfolio');save();go('caseResult')},
 toggleSave:d=>{state.saved=state.saved.includes(d.id)?state.saved.filter(id=>id!==d.id):[...state.saved,d.id];save();render();toast(state.saved.includes(d.id)?'Lowongan disimpan.':'Lowongan dihapus dari tersimpan.')},
 jobFilter:d=>{route.data.filter=d.id;render()},companyTab:d=>{route.data.tab=d.id;render()},noticeFilter:d=>{route.data.filter=d.id;render()},
 openNotice:d=>{const n=state.notifications.find(n=>n.id===d.id);if(!n)return;n.read=true;save();go(n.target,n.data)},readAll(){state.notifications.forEach(n=>n.read=true);save();render();toast('Semua notifikasi ditandai dibaca.')},
 advance:d=>{advanceApplication(state,d.id,d.outcome);save();render();toast('Status diubah oleh simulator, bukan perusahaan.')},
