function fitDevice(){const height=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--device-height'))||774;document.documentElement.style.setProperty('--device-scale',Math.min(1,Math.max(.42,(innerHeight-164)/height)).toFixed(4))}window.addEventListener('resize',fitDevice);fitDevice();